export function renderSharedSummary(s, escape) {
  return `${"cycle" in s ? `<section class="shared-detail"><h3>Chu kỳ</h3><p>${s.cycle ? (s.cycle.inPeriod ? "Em đang trong kỳ kinh." : `Ngày ${Number(s.cycle.day)} của chu kỳ. Kỳ tiếp theo ước tính: ${escape(s.cycle.nextDate || "Chưa đủ dữ liệu")}.`) : "Chưa ghi nhận chu kỳ."}</p></section>` : ""}${"mood" in s ? `<section class="shared-detail"><h3>Tâm trạng hôm nay</h3><p>${escape(s.mood || "Chưa ghi nhận")}</p></section>` : ""}${"note" in s ? `<section class="shared-detail"><h3>Ghi chú và triệu chứng</h3><p>${escape(s.note || "Chưa có ghi chú")}</p>${(s.symptoms || []).length ? `<p>${escape(s.symptoms.join(", "))}</p>` : ""}</section>` : ""}${!("cycle" in s) && !("mood" in s) && !("note" in s) ? '<p class="shared-empty">Em chưa bật chia sẻ thông tin.</p>' : ""}`;
}
